EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR SELECT id, name FROM users;
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR SELECT id, name FROM products WHERE price > 50;
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
DECLARE result ARRAY DEFAULT [];
BEGIN
    LET cur CURSOR FOR SELECT id, name FROM items;
    FOR rec IN cur DO
        result := ARRAY_APPEND(result, rec.name);
    END FOR;
    RETURN result;
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur1 CURSOR FOR SELECT id, name FROM users;
    LET cur2 CURSOR FOR SELECT id, name FROM products;
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR
        SELECT o.id, u.name
        FROM orders o
        JOIN users u ON o.user_id = u.id;
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR SELECT id, score FROM scores ORDER BY score DESC;
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR
        SELECT product, SUM(amount) as total
        FROM sales
        GROUP BY product;
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR SELECT id FROM data LIMIT 2;
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR
        SELECT table_name
        FROM information_schema.tables
        WHERE table_schema = 'PUBLIC';
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR
        SELECT constraint_name, table_schema, table_name
        FROM information_schema.table_constraints
        WHERE table_schema = 'BASE';
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
DECLARE result VARCHAR DEFAULT 'start';
BEGIN
    LET count INTEGER := 0;
    LET cur CURSOR FOR SELECT id FROM items;
    LET total INTEGER := 10;
    RETURN result;
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR
        SELECT value FROM (
            SELECT value * 2 as value FROM numbers
        );
    RETURN 'success';
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    LET cur CURSOR FOR
        SELECT id, amount
        FROM orders
        WHERE status = 'active'
            AND amount > 50
        ORDER BY amount DESC
        LIMIT 10;
    RETURN 'success';
END;
$$;
